package career.assistant.dashboard;
import career.assistant.job.repository.JobRepository; import career.assistant.company.repository.CompanyRepository; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {private final JobRepository jobs;private final CompanyRepository companies;public DashboardController(JobRepository j,CompanyRepository c){jobs=j;companies=c;} @GetMapping("/summary") public Map<String,Long> summary(){return Map.of("totalJobs",jobs.count(),"newJobs",jobs.countByStatus("NEW"),"highScoreJobs",jobs.countByStatus("HIGH_SCORE"),"pendingReview",jobs.countByStatus("PENDING_REVIEW"),"autoApplied",jobs.countByStatus("AUTO_APPLIED"),"successfullyApplied",jobs.countByStatus("MANUALLY_APPLIED")+jobs.countByStatus("AUTO_APPLIED"),"failedApplications",jobs.countByStatus("FAILED"),"companies",companies.count());}}
